61	  /// that duration, it will wait for analysis to complete.
62	  ///
63	  /// This is useful to avoid the race condition where analysis hasn't started
64	  /// yet after a file change.
65	  Future<void> waitForAnalysis({Duration delay = const Duration(milliseconds: 100)}) async {
66	    if (_isAnalyzing) {
67	      await onAnalyzing.firstWhere((bool analyzing) => !analyzing);
68	    }
69	    if (delay != Duration.zero) {
70	      // Wait for analysis to potentially start.
71	      try {
