32	    final String currentDirectory = (workingDirectory ?? fileSystem.currentDirectory).path;
33	    final Set<String> items = findDirectories(argResults, fileSystem);
34	
35	    if (isFlutterRepo) {
36	      // check for conflicting dependencies
37	      final dependencies = PackageDependencyTracker();
38	      dependencies.checkForConflictingDependencies(repoPackages, dependencies);
39	      items.add(flutterRoot);
40	      if (argResults.wasParsed('current-package') && (argResults['current-package'] as bool)) {
41	        items.add(currentDirectory);
42	      }
43	    } else {
44	      if ((argResults['current-package'] as bool) && items.isEmpty) {
45	        items.add(currentDirectory);
46	      }
47	    }
48	
49	    if (items.isEmpty) {
50	      throwToolExit('Nothing to analyze.', exitCode: 0);
51	    }
52	
53	    final analysisCompleter = Completer<void>();
54	    final errors = <AnalysisError>[];
55	
56	    final server = AnalysisServer(
57	      sdkPath,
58	      items.toList(),
59	      fileSystem: fileSystem,
60	      platform: platform,
61	      logger: logger,
62	      processManager: processManager,
63	      terminal: terminal,
64	      protocolTrafficLog: protocolTrafficLog,
65	      suppressAnalytics: suppressAnalytics,
66	    );
67	
68	    Stopwatch? timer;
69	    Status? progress;
70	    try {
71	      StreamSubscription<bool>? subscription;
72	
73	      void handleAnalysisStatus(bool isAnalyzing) {
74	        if (!isAnalyzing) {
75	          analysisCompleter.complete();
76	          subscription?.cancel();
77	          subscription = null;
78	        }
79	      }
80	
81	      subscription = server.onAnalyzing.listen(
82	        (bool isAnalyzing) => handleAnalysisStatus(isAnalyzing),
83	      );
84	
