86	        errors.addAll(fileErrors.errors);
87	      }
88	
89	      server.onErrors.listen(handleAnalysisErrors);
90	
91	      await server.start();
92	      // Completing the future in the callback can't fail.
93	      unawaited(
94	        server.onExit.then<void>((int? exitCode) {
95	          if (!analysisCompleter.isCompleted) {
96	            analysisCompleter.completeError(
97	              // Include the last 20 lines of server output in exception message
98	              Exception(
99	                'analysis server exited with code $exitCode and output:\n${server.getLogs(20)}',
100	              ),
101	            );
102	          }
103	        }),
104	      );
105	
106	      // collect results
107	      timer = Stopwatch()..start();
108	      final String message = items.length > 1
109	          ? '${items.length} ${items.length == 1 ? 'item' : 'items'}'
110	          : fileSystem.path.basename(items.first);
111	      progress = argResults['preamble'] == true
112	          ? logger.startProgress('Analyzing $message...')
113	          : null;
114	
115	      await analysisCompleter.future;
116	    } finally {
117	      await server.dispose();
118	      progress?.cancel();
119	      timer?.stop();
120	    }
121	
122	    // emit benchmarks
123	    if (isBenchmarking) {
124	      writeBenchmark(timer, errors.length);
125	    }
126	
127	    // --write
128	    dumpErrors(errors.map<String>((AnalysisError error) => error.toLegacyString()));
129	
130	    // report errors
131	    if (errors.isNotEmpty && (argResults['preamble'] as bool)) {
132	      logger.printStatus('');
133	    }
134	    errors.sort();
135	    for (final error in errors) {
136	      logger.printStatus(error.toString(), hangingIndent: 7);
137	    }
138	
139	    final int errorCount = errors.length;
140	    final String seconds = (timer.elapsedMilliseconds / 1000.0).toStringAsFixed(1);
141	    final String errorsMessage = AnalyzeBase.generateErrorsMessage(
142	      issueCount: errorCount,
143	      seconds: seconds,
144	    );
145	
146	    if (errorCount > 0) {
147	      logger.printStatus('');
148	      throwToolExit(errorsMessage, exitCode: _isFatal(errors) ? 1 : 0);
149	    }
150	
151	    if (argResults['congratulate'] as bool) {
152	      logger.printStatus(errorsMessage);
153	    }
154	
155	    if (server.didServerErrorOccur) {
156	      throwToolExit('Server error(s) occurred. (ran in ${seconds}s)');
157	    }
158	  }
