160	  bool _isFatal(List<AnalysisError> errors) {
161	    for (final error in errors) {
162	      final AnalysisSeverity severityLevel = error.writtenError.severityLevel;
163	      if (severityLevel == AnalysisSeverity.error) {
164	        return true;
165	      }
166	      if (severityLevel == AnalysisSeverity.warning && argResults['fatal-warnings'] as bool) {
167	        return true;
168	      }
169	      if (severityLevel == AnalysisSeverity.info && argResults['fatal-infos'] as bool) {
170	        return true;
171	      }
172	    }
173	    return false;
174	  }
